CREATE TABLE IF NOT EXISTS users (
 id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, username VARCHAR(80) NOT NULL UNIQUE, name VARCHAR(160) NOT NULL, password_hash VARCHAR(255) NOT NULL, role ENUM('admin','editor','viewer') NOT NULL DEFAULT 'viewer', active TINYINT(1) NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS settings (`key` VARCHAR(80) PRIMARY KEY, `value` TEXT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS locations (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(200) NOT NULL, parent_id INT UNSIGNED NULL, description TEXT, FOREIGN KEY(parent_id) REFERENCES locations(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS dimensions (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL UNIQUE, description TEXT, low_label VARCHAR(200) NOT NULL DEFAULT 'Kein Bezug', high_label VARCHAR(200) NOT NULL DEFAULT 'Starker Bezug', weight DECIMAL(7,4) NOT NULL DEFAULT 1, enabled TINYINT(1) NOT NULL DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS items (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, title VARCHAR(255) NOT NULL, description TEXT, tags TEXT, category VARCHAR(140) NOT NULL DEFAULT '', location_id INT UNSIGNED NULL, quantity INT UNSIGNED NOT NULL DEFAULT 1, image_path VARCHAR(255) NULL, created_by INT UNSIGNED NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(location_id) REFERENCES locations(id) ON DELETE SET NULL, FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL, INDEX(title), INDEX(category)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS item_vectors (item_id INT UNSIGNED NOT NULL, dimension_id INT UNSIGNED NOT NULL, base_value DECIMAL(5,4) NOT NULL DEFAULT 0.5, learned_value DECIMAL(5,4) NOT NULL DEFAULT 0.5, confidence DECIMAL(5,4) NOT NULL DEFAULT 0, applicable TINYINT(1) NOT NULL DEFAULT 1, PRIMARY KEY(item_id,dimension_id), FOREIGN KEY(item_id) REFERENCES items(id) ON DELETE CASCADE, FOREIGN KEY(dimension_id) REFERENCES dimensions(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS keywords (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, term VARCHAR(190) NOT NULL UNIQUE, usage_count INT UNSIGNED NOT NULL DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS keyword_vectors (keyword_id INT UNSIGNED NOT NULL, dimension_id INT UNSIGNED NOT NULL, initial_value DECIMAL(5,4) NOT NULL DEFAULT 0.5, value DECIMAL(5,4) NOT NULL DEFAULT 0.5, confidence DECIMAL(5,4) NOT NULL DEFAULT 0, PRIMARY KEY(keyword_id,dimension_id), FOREIGN KEY(keyword_id) REFERENCES keywords(id) ON DELETE CASCADE, FOREIGN KEY(dimension_id) REFERENCES dimensions(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS associations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, source_type ENUM('keyword','item') NOT NULL, source_id INT UNSIGNED NOT NULL, target_type ENUM('keyword','item') NOT NULL, target_id INT UNSIGNED NOT NULL, strength DECIMAL(9,4) NOT NULL DEFAULT 0, interactions INT UNSIGNED NOT NULL DEFAULT 0, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY pair_unique(source_type,source_id,target_type,target_id), INDEX(source_type,source_id), INDEX(target_type,target_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS searches (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, session_token VARCHAR(64) NOT NULL, user_id INT UNSIGNED NULL, query VARCHAR(255) NOT NULL, keyword_id INT UNSIGNED NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX(session_token,created_at), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL, FOREIGN KEY(keyword_id) REFERENCES keywords(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS interactions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, search_id BIGINT UNSIGNED NULL, item_id INT UNSIGNED NULL, event ENUM('click','basket','borrow') NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(search_id) REFERENCES searches(id) ON DELETE SET NULL, FOREIGN KEY(item_id) REFERENCES items(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS loans (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, borrower VARCHAR(180) NOT NULL, contact VARCHAR(180) NOT NULL DEFAULT '', note TEXT, due_date DATE NULL, created_by INT UNSIGNED NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS loan_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, loan_id BIGINT UNSIGNED NOT NULL, item_id INT UNSIGNED NULL, item_title VARCHAR(255) NOT NULL, qty INT UNSIGNED NOT NULL, returned_qty INT UNSIGNED NOT NULL DEFAULT 0, search_id BIGINT UNSIGNED NULL, FOREIGN KEY(loan_id) REFERENCES loans(id) ON DELETE CASCADE, FOREIGN KEY(item_id) REFERENCES items(id) ON DELETE SET NULL, FOREIGN KEY(search_id) REFERENCES searches(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS audit_log (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id INT UNSIGNED NULL, action VARCHAR(100) NOT NULL, entity VARCHAR(50) NOT NULL, entity_id BIGINT UNSIGNED NULL, details TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX(created_at), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
